package com.arjunren.hospital.dto;
import com.arjunren.hospital.domain.*;import com.arjunren.hospital.entity.*;import jakarta.validation.constraints.*;import java.time.*;import java.util.List;
public final class Dtos{private Dtos(){}public record LoginRequest(@Email@NotBlank String email,@NotBlank@Size(max=72)String password){}public record UserResponse(Long id,String email,String name,Role role){public static UserResponse of(AppUser u){return new UserResponse(u.getId(),u.getEmail(),u.getName(),u.getRole());}}public record TokenResponse(String accessToken,String tokenType,Instant expiresAt,UserResponse user){}public record DoctorCreate(@NotBlank@Size(max=120)String name,@Email@NotBlank String email,@NotBlank@Size(min=12,max=72)String password,@NotBlank@Size(max=40)String licenseNumber,@NotBlank@Size(max=120)String specialty,@Min(10)@Max(240)int slotMinutes){}public record PatientCreate(@NotBlank@Size(max=120)String name,@Email@NotBlank String email,@NotBlank@Size(min=12,max=72)String password,@NotBlank@Size(max=30)String medicalRecordNumber,@NotNull@Past LocalDate dateOfBirth,@Size(max=30)String phone){}public record AppointmentCreate(@NotNull Long doctorId,Long patientId,@NotNull@Future Instant startsAt,@NotBlank@Size(max=500)String reason){}public record CompleteRequest(@NotBlank@Size(max=1000)String diagnosis,@NotBlank@Size(max=2000)String treatment){}public record DoctorResponse(Long id,Long userId,String name,String specialty,String licenseNumber,int slotMinutes){public static DoctorResponse of(DoctorProfile d){return new DoctorResponse(d.getId(),d.getUser().getId(),d.getUser().getName(),d.getSpecialty(),d.getLicenseNumber(),d.getSlotMinutes());}}public record PatientResponse(Long id,Long userId,String name,String medicalRecordNumber,LocalDate dateOfBirth,String phone){public static PatientResponse of(PatientProfile p){return new PatientResponse(p.getId(),p.getUser().getId(),p.getUser().getName(),p.getMedicalRecordNumber(),p.getDateOfBirth(),p.getPhone());}}public record AppointmentResponse(Long id,Long doctorId,String doctorName,Long patientId,String patientName,Instant startsAt,Instant endsAt,String reason,AppointmentStatus status,String diagnosis,String treatment){public static AppointmentResponse of(Appointment a){return new AppointmentResponse(a.getId(),a.getDoctor().getId(),a.getDoctor().getUser().getName(),a.getPatient().getId(),a.getPatient().getUser().getName(),a.getStartsAt(),a.getEndsAt(),a.getReason(),a.getStatus(),a.getDiagnosis(),a.getTreatment());}}public record PageResponse<T>(List<T>items,int page,int size,long totalElements,int totalPages){}
}
